if(first.length)Promise.all(first.map(function(n){return L.ensure(n);})).then(function(){lateDone(false);},function(){lateDone(true);});
else setTimeout(function(){lateDone(false);},0);
var sid='',chars=null;
try{var us=HK.UI&&HK.UI.state?HK.UI.state():null;sid=us?us.scenId:'';chars=us?us.chars:null;}catch(e){sid='';}
if(!sid|| !chars){try{var raw=HK.store&&HK.store.get?HK.store.get('state',null):null;if(!sid)sid=raw&&raw.scenId;if(!chars)chars=raw&&raw.chars;}catch(e){}}
if(sid&&SC[sid])L.ensure(sid).then(null,function(){});
if(Array.isArray(chars)&&chars.length)L.ensureTones(chars).then(null,function(){});
