when:function(ctx,a,b){var r=R(ctx,a,b);return r.aff>45&&r.att>45&& !ctx.pair(a,b).confessed[a.i]&& !ctx.pair(a,b).couple&&(!HK.Poly||HK.Poly.canTry(ctx,a,b));},
