if(w&& !((S.lhResc||{})[a.i+'>'+b.i]===w))cand.push({k:'rescue',a:a,b:b,w:w,p:3});
if(follow(S,a,b,'regret'))cand.push({k:'regret',a:a,b:b,p:2});
if(follow(S,a,b,'makeup'))cand.push({k:'makeup',a:a,b:b,p:1.5});
