if(/でしょうか$/.test(s)&& /(何|誰|どこ|いつ|どれ|どっち|なん)/.test(s))return s.replace(/でしょうか$/,'っすかね');
if(/でしょう?か?$/.test(s)&& /(何|誰|どこ|いつ|どれ|どっち|なん)/.test(s))return s;
