HK.pairKey=key;
function Ctx(input){
var self=this;
this.input=input;
HK._curCtx=this;
this.scen=HK.SCENARIOS[input.scenId];
this.seed=input.seed;
this.rng=HK.rng(input.seed);
this.env={};
var defs=this.scen.env.concat(HK.GLOBAL_ENV);
defs.forEach(function(e){
if(e.sparse&& !(input.env&&input.env[e.id]!=null))return;
self.env[e.id]=input.env&&input.env[e.id]!=null?input.env[e.id]:e.def;
});
this.env.ct=input.env&&input.env.ct!=null?String(input.env.ct):'';
this.chaos=this.env.chaos/100;
this.log=[];
this.history=[];
this.pf={};
this.flags={};
this.stepIndex=0;
this.label='';
this.chars=input.chars.map(function(c,i){
var pc=(input.perChar&&input.perChar[i])||{};
return{
i:i,ng:Array.isArray(c.loveNG)?c.loveNG.filter(function(x){return x>=0;}):[],name:c.name,eg:c.eg,tr:HK.traits(c.eg),memo:c.memo||'',gender:c.gender||'',likes:c.likes||'',tone:c.tone||'',fp:c.fp||'',pos:c.pos||'',posLike:c.posLike||'',futa: !!c.futa,lock:HK.lockFirst(c.loveLock),locks:HK.parseLocks(c.loveLock),sexLock:HK.sexLockOf(c.sexLock),call:c.call||'',calls:c.calls||null,keigo:c.keigo||null,age: +c.age||0,bmonth: +c.bmonth||0,keigoOlder: !!c.keigoOlder,
hp:100,alive:true,out:false,stress:0,
stats:{},statsRaw:pc.stats||{},weaponPick:pc.weapon||'random',
actionPick:pc.action||'auto',goalPick:pc.goal||'auto',role:pc.role||'',pick:pc.pick||{},
action:null,goal:null,focus:null,flags:{},
cats:{},odd:[],diedAt:null,killedBy:null,fate:'',fateNote:''
};
});
this.chars.forEach(function(c,i){c.persona=HK.personaOf(c);HK.charFlags(input.chars[i],c,input.scenId);});
this.chars.forEach(function(c,i){if(input.chars[i].moanTone)c.moanTone=String(input.chars[i].moanTone);});
this.rel=this.chars.map(function(){return[];});
}
Ctx.prototype.R=function(a,b){return this.rel[a.i][b.i];};
HK.charFlags=function(src,dst,scenId){
if(!src|| !dst)return dst;
var core= !!(scenId&&HK.State&&HK.State.R18_CORE[scenId]);
dst.noR18= !!src.noR18&& !HK.SAFE_ON&& !core;
dst.locks=HK.parseLocks(src.loveLock);
if(dst.lock==null&&dst.locks.length)dst.lock=dst.locks[0];
var SL=HK.sexLockRead(src);
dst.sexLocks=SL.locks;
dst.sexLock=SL.k==='any'?'any':SL.locks?SL.locks[0]:null;
dst.sexMob= !!(SL.locks&&SL.mob);
dst.noMob= !!dst.noMob||(!HK.SAFE_ON&& !!(SL.locks&& !SL.mob));
dst.trio=src.trio==='no'?'no':'';
dst.posNpc=HK.Pos&&HK.Pos.npcValid?HK.Pos.npcValid(src.posNpc):src.posNpc==='bottom'?'bottom':'';
dst.alcohol=HK.ALC_OK(src.alcohol)? +src.alcohol:0;
if(HK.Attr)HK.Attr.copy(dst,src);
dst.faithful= !!src.faithful;
return dst;
};
HK.parseLocks=function(v){
if(Array.isArray(v))return v.map(function(x){return+x;}).filter(function(x,i,l){return!isNaN(x)&&x>= -1&&l.indexOf(x)===i;});
if(v===''||v==null||typeof v==='boolean'||isNaN(+v))return[];
return[+v];
};
HK.lockFirst=function(v){var L=HK.parseLocks(v);return L.length?L[0]:null;};
HK.sexLockOf=function(v){if(v==='any')return v;if(typeof v==='string'&&v&&isNaN(+v))return null;return HK.lockFirst(v);};
HK.sexLocksOf=function(v){if(typeof v==='string'&&v&&isNaN(+v))return null;var L=HK.parseLocks(v);return L.length?L:null;};
HK.sexLockRead=function(src){
var v=src?src.sexLock:null;
if(v==='any')return{k:'any',locks:null,mob:true};
var old=v==='lover'||v==='loverOnly',L=old?HK.parseLocks(src.loveLock):HK.sexLocksOf(v)||[];
if(!L.length)return{k:null,locks:null,mob:true};
return{k:'pick',locks:L,mob:old?v==='lover': !!src.sexLockMob};
};
HK.locks=function(c){if(!c)return[];if(Array.isArray(c.locks))return c.locks;return c.lock!=null?[c.lock]:[];};
HK.lockAny=function(a){return HK.locks(a).length>0;};
HK.lockTo=function(a,b){return!!b&&HK.locks(a).indexOf(b.i)>=0;};
HK.lockOut=function(a,b){var L=HK.locks(a);return L.length>0&& !(b&&L.indexOf(b.i)>=0);};
HK.lockPeople=function(chars,a){return HK.locks(a).map(function(k){return k>=0&&chars?chars[k]:null;}).filter(function(x){return x&&x!==a;});};
HK.lockNames=function(chars,a){return HK.lockPeople(chars,a).map(function(x){return x.name;}).join('・');};
HK.sexLockOut=function(x,y){
if(!x|| !y)return false;
if(Array.isArray(x.sexLocks))return x.sexLocks.indexOf(y.i)<0;
return typeof x.sexLock==='number'&&x.sexLock!==y.i;
};
HK.ALC_OK=function(v){return v!=null&&v!==''&& +v>=1&& +v<=5&&Math.floor(+v)=== +v;};
HK.ALC_LABEL={1:'弱い',2:'やや弱い',3:'ふつう',4:'強い',5:'ザル'};
HK.alcLevel=function(c){
if(!c)return 3;
if(HK.ALC_OK(c.alcohol))return+c.alcohol;
if(c._alc)return c._alc;
var t=c.tr||{},s=(c.name||'')+'sake',h=7;
for(var i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))%9973;
var v=(t.cold||0.5)*0.3+(t.cp||0.5)*0.2+(1-(t.ac==null?0.5:t.ac))*0.2+h/9973*0.3;
return(c._alc=v>0.72?5:v>0.58?4:v>0.45?3:v>0.33?2:1);
};
HK.drunkRate=function(c){return c&&HK.ALC_OK(c.alcohol)?[0,1.7,1.3,1,0.7,0.35][+c.alcohol]:1;};
HK.TIE_EV_RE= /^(?:tie_|rt_|om_tie|zb_(?:boss|worship|benefactor|relative|spouse))/;
HK.honmeiDesperate=function(ctx,c){
var aph=c&&c.flags&&c.flags.aphro||0;
var room=ctx&&ctx.scen&&ctx.scen.id==='whiteroom'&&ctx.rules&&ctx.rules.some(function(r){return r.k==='h'||r.k==='kiss';});
return!!c&&((c.stress||0)>75||aph>1.2||(room&&(c.stress||0)>55)||(c.m&&c.m.heat>70));
};
HK.honmeiFactor=function(ctx,a,b){
if(!a|| !b)return 1;
var f=1;
if(a.honmei!=null)f*=a.honmei===b.i?2.2:HK.honmeiDesperate(ctx,a)?0.75:0.2;
if(b.honmei!=null&&b.honmei!==a.i)f*=HK.honmeiDesperate(ctx,b)?0.8:0.35;
return f;
};
HK.ngPairHard=function(a,b){
if(!a|| !b||a===b)return false;
if((a.ng&&a.ng.indexOf(b.i)>=0)||(b.ng&&b.ng.indexOf(a.i)>=0))return true;
if(HK.noLovePair(a,b))return true;
return HK.lockOut(a,b)||HK.lockOut(b,a);
};
HK.noLovePair=function(a,b){return!!(a&&b&&a!==b&&((a.noLove&&a.noLove.indexOf(b.i)>=0)||(b.noLove&&b.noLove.indexOf(a.i)>=0)));};
HK.ngPair=function(a,b){
if(!a|| !b||a===b)return false;
if(HK.ngPairHard(a,b))return true;
return!!((a.coNG&&a.coNG.indexOf(b.i)>=0)||(b.coNG&&b.coNG.indexOf(a.i)>=0));
};
