if(f==='att'&&d[f]>0)m=pf.chem;
if(f==='ten'&&d[f]>0)m=pf.fric;
if(f==='att'&&d[f]>0&&this.env&&this.env.romance!=null)m*=0.5+this.env.romance/100;
