var Q_END= /[？?]」(?:と[^。「」]{0,16}(?:訊|尋ね|聞)いた)?。?$/,Q_PASS= /[？?]」と[^。「」]{0,16}(?:訊|尋ね|聞)(?:か|ね)れた。?$/;
