function tagValue(tag,A,B,extra){
var av=function(k){return((A.eg[k]||0)+(B.eg[k]||0))/40;};
if(tag==='sweet')return HK.clamp((av('NP')+av('FC'))/2*0.6+extra.att/100*0.4);
if(tag==='heat')return HK.clamp(av('FC')*0.5+extra.att/100*0.5);
var diff=HK.FACTORS.reduce(function(s,k){return s+Math.abs(A.eg[k]-B.eg[k]);},0)/100;
if(tag==='diff')return Math.min(1,diff*2.5);
if(tag==='same')return 1-Math.min(1,diff*2.5);
var m= /^(CP|NP|A|FC|AC)([+-])$/.exec(tag);
if(!m)return 0.5;
var v=av(m[1]);
return m[2]==='+'?v:1-v;
}
OM.pickDate=function(rng,A,B,extra,used){
var best=null,bs= -1e9;
OM.DATES.forEach(function(d){
if(used&&used[d[0]])return;
var tags=d[3].split(' ');
var vals=tags.map(function(t){return{t:t,v:(tagValue(t,A,B,extra)-0.5)/0.2};});
var sc=vals.reduce(function(s,x){return s+Math.max(-2.5,Math.min(2.5,x.v));},0)/vals.length+rng()*0.7;
if(sc>bs){bs=sc;vals.sort(function(x,y){return y.v-x.v;});best={name:d[0],desc:d[1],why:vals.filter(function(x){return x.v>0;}).slice(0,2).map(function(x){return OM.DATE_WHY[x.t];}).filter(Boolean)};}
});
return best;
};
