var G_TRIO=L('{a}と{b}と{c}は、三人で一つのソファに座って映画を観た。真ん中の席は、日替わりで交代することに決めていた。|[m]朝の洗面台の前で、{a}と{b}と{c}の歯ブラシが三本並んでいた。誰からともなく、三人で笑った。|{a}は、{b}と{c}の分まで弁当を作った。三つの弁当箱は、色違いのおそろいだった。|{a}と{b}と{c}は、休日の予定を三人で決めた。誰か一人が我慢することは、もうなかった。');
var FINAL={
0:L('{n}日目の夜。{a}と{b}は、まだ互いのことをよく知らないままだった。それでも、明日はもう少し話してみようと思った。|{n}日が過ぎても、{a}と{b}の距離はあまり変わらなかった。ただ、名前を呼ぶ声は、最初の日より自然になっていた。|最後の日、{a}は{b}に小さく会釈をした。{b}も、少しだけ笑って返した。'),
1:L('{n}日目の夜。{a}と{b}は、いつものように「また明日｜＝｜また明日会いましょう」と言い合った。それ以上でも、それ以下でもない、心地いい距離だった。|{n}日が過ぎても、{a}と{b}は友人のままだった。けれど、その友情は最初の日よりずっと深くなっていた。|最後の日、{a}と{b}は並んで夜空を眺めた。名前のない関係でも、隣にいるのが当たり前になっていた。'),
2:L('{n}日目の夜。{a}も{b}も、今日こそ言おうと思って、言えなかった。両片想いのまま、また明日が来る。|{a}と{b}は、最後まで想いを口にしなかった。それでも、互いの気持ちはすぐそこにあった。|{n}日目、{a}は{b}の背中を見送りながら、次こそは、と思った。{b}も同じことを思っていた。'),
3:L('{n}日目の夜。恋人になった{a}と{b}は、明日の約束をしてから、おやすみを言い合った。|{a}と{b}は、{n}日分の思い出を指折り数えた。恋人になってからの日々は、あっという間だった。|{n}日目、{b}は{a}の手を握って言った。{b}「明日も、明後日も、よろしく｜明日も、明後日も、よろしく頼む｜明日も、明後日も、よろしくお願いします」'),
4:L('{n}日目の夜。同じ部屋の明かりを、{a}と{b}は二人で消した。|{a}と{b}の暮らす部屋には、{n}日分の暮らしの匂いがしみついていた。|{n}日目、{a}は二人分の食器を洗いながら、これが当たり前になったことを不思議に思った。'),
5:L('{n}日目の夜。指輪をはめた手で、{a}と{b}はいつものようにおやすみを言い合った。|{a}と{b}の薬指には、おそろいの指輪が光っていた。式はなくても、二人には十分だった。|{n}日目、{b}は指輪を眺めながら言った。{b}「これからの毎日も、きっと楽しい｜これからの毎日も、きっと楽しいだろう｜これからの毎日も、きっと楽しいです」'),
broke:L('{n}日目の夜。{a}と{b}は、もう恋人ではなかった。それでも、すれ違うときに小さく会釈をした。|{a}と{b}の{n}日間は、思っていたのとは違う形で終わった。|最後の日、{a}は{b}の背中を見送った。もう、追いかけることはなかった。')
};
var AFTER={
0:L('{a}と{b}は、その後も顔を合わせれば挨拶をする仲になった。|{a}と{b}が本当に親しくなるのは、もう少し先のことになりそうだった。|{a}と{b}は、その後も同じ街で、少しずつすれ違い続けた。'),
1:L('{a}と{b}は、その後も困ったときに真っ先に連絡し合う友人であり続けた。|{a}と{b}は、休みが合うたびに出かける仲になった。|{a}と{b}の友情は、何年たっても変わらなかった。'),
2:L('{a}と{b}は、その後もしばらく、互いの言葉を待ち続けた。|{a}と{b}が同じ言葉を口にするのは、次の季節のことだった。|{a}と{b}の距離は、近いまま、まだ縮まりきらなかった。'),
3:L('{a}と{b}は、その後も季節ごとに新しいデートの行き先を探した。|{a}と{b}は、記念日のたびに、最初のデートの店へ行くようになった。|{a}と{b}のスマホの写真は、ほとんどが二人で写ったものになった。'),
4:L('{a}と{b}の部屋には、その後も少しずつ二人のものが増えていった。|{a}と{b}は、休日の朝ごはんを交代で作る決まりを、ずっと守り続けた。|{a}と{b}の暮らしは、ケンカも仲直りも含めて、すっかり二人の形になった。'),
5:L('{a}と{b}は、その後も指輪を外さなかった。式は、いつか気が向いたら、ということになった。|{a}と{b}は、年に一度、指輪を交換した日に同じ店で夕飯を食べた。|{a}と{b}の毎日は、約束をしたあとも、いつもどおりに続いていった。'),
broke:L('{a}と{b}は、それぞれの道を歩き始めた。ときどき、互いの近況を風の便りで聞いた。|{a}と{b}は、時間をかけて、友人に戻っていった。|{a}と{b}は、あの日々をいい思い出として胸にしまった。')
};
var AFTER3={
lost:L('{a}は、その後しばらく二人と距離を置いた。けれど、また三人で笑える日が来た。|{a}は失恋の痛みを抱えたまま、それでも二人の友人であり続けた。|{a}は、次の恋を探しに街へ出かけるようになった。'),
friend:L('{a}は、その後も二人のいちばんの友人として、ときどき顔を出した。|{a}は、二人の幸せそうな顔を見るのが、いつの間にか楽しみになっていた。|{a}は、二人のケンカの仲裁役として、すっかり頼りにされるようになった。'),
trio:L('{a}は、その後も三人で並んで眠る夜を大事にした。|{a}と二人の暮らしは、三人分の食器と三人分の笑い声で満ちていた。|{a}は、三人で撮った写真を、玄関にいちばん大きく飾った。')
};
function F(ctx){return ctx.ft;}
function stOf(ctx,a,b){var k=K(a,b),x=ctx.ft.st[k];if(!x)x=ctx.ft.st[k]={s:0,at:{},since:0,cool: -99,tried:0,broke:false,oneway:{}};return x;}
function setSt(ctx,a,b,s){var x=stOf(ctx,a,b);if(x.s===s)return;x.s=s;if(x.at[s]==null)x.at[s]=ctx.ft.day;x.since=ctx.ft.day;}
function sameHome(ctx,a,b){return ctx.ft.home[a.i]===ctx.ft.home[b.i];}
function couple(ctx,a,b){return!!ctx.pair(a,b).couple;}
function famTie(ctx,a,b){return!!(ctx.pair(a,b).kin||(HK.Daily&&HK.Daily.famTie&&HK.Daily.famTie(ctx,a,b)));}
function loveOk(ctx,a,b){return HK.canLove(a,b)&&HK.canLove(b,a)&& !HK.ngPair(a,b)&& !famTie(ctx,a,b);}
function colleague(ctx,a,b){return!!(HK.Ties&&(HK.Ties.has(ctx,a,b,'colleague')||HK.Ties.has(ctx,a,b,'boss')));}
function onTrip(ctx,c){var T=ctx.ft.trip;return!!(T&&T.day===ctx.ft.day&&T.m.indexOf(c.i)>=0);}
function together(ctx,a,b){
var f=ctx.ft,t=f.t,k=K(a,b),pl=f.plan[k]||{},sh=sameHome(ctx,a,b);
if(f.trip&&f.trip.day===f.day){var ta=onTrip(ctx,a),tb=onTrip(ctx,b);if(ta||tb)return ta&&tb;}
if(t===0)return sh||f.slept[k]===f.day-1;
if(t===1)return f.hol?sh|| !!pl.date|| !!f.gplan:colleague(ctx,a,b);
if(t===2)return sh|| !!pl.date|| !!pl.eve|| !!f.gplan;
return sh|| !!pl.visit;
}
function pairs(ctx){var P=ctx.present(),o=[];for(var i=0;i<P.length;i++)for(var j=i+1;j<P.length;j++)o.push([P[i],P[j]]);return o;}
function three(ctx,a,b){var P=ctx.present();if(P.length<3)return null;var c=P.filter(function(x){return x!==a&&x!==b;})[0];return c&&together(ctx,a,c)&&together(ctx,b,c)&&together(ctx,a,b)?c:null;}
function monthNow(ctx){return dateOf(ctx.env,ctx.ft.day).m;}
function seasonNow(ctx){var m=monthNow(ctx);return m>=3&&m<=5?'spring':m>=6&&m<=8?'summer':m>=9&&m<=11?'autumn':'winter';}
function spotHere(ctx,a,b){
var f=ctx.ft,t=f.t;
if(onTrip(ctx,a))return t===3?'温泉宿':'旅先';
var sh= !b||sameHome(ctx,a,b);
if(t===0)return sh||(b&&f.slept[K(a,b)]===f.day-1)?'自宅':'';
if(t===1)return f.hol?(sh&&ctx.rng()<0.5?'自宅':'街'):'';
if(t===2)return sh?'自宅':'街';
return sh||(b&&(f.plan[K(a,b)]||{}).visit)?'自宅':'';
}
function homeLovers(ctx,a,b){return couple(ctx,a,b)&&sameHome(ctx,a,b);}
function emit(ctx,o){
var e=ctx.act2({actors:o.actors,cat:o.cat||'bond',text:o.text,why:o.why,mag:o.mag||0,fx:o.fx,sex:o.sex});
if(e&&o.tag)e.ftTag=o.tag;
return e;
}
function relFx(ctx,a,b,ab,ba){return function(){if(ab)ctx.mod(a,b,ab);if(ba)ctx.mod(b,a,ba);};}
function bump(ctx,c,d,why){if(HK.Emo&&HK.Emo.bump)HK.Emo.bump(ctx,c,d,why);}
var EV=[];
function ev(o){
var e={
id:o.id,cat:o.cat,scope:o.scope||'pair',noOdd:true,
when:function(ctx,a,b){
var f=ctx.ft;if(!f)return false;
if(o.tm&&o.tm.indexOf(TC.charAt(f.t))<0)return false;
if(e.scope==='pair'&&(!b|| !together(ctx,a,b)))return false;
if(o.need&& !o.need(ctx,a,b))return false;
return has(ctx,o.pool(ctx,a,b));
},
w:function(ctx,a,b){return typeof o.w==='function'?o.w(ctx,a,b):o.w;},
run:function(ctx,a,b){
var c=o.third?o.third(ctx,a,b):null;
if(o.third&& !c)return null;
var t=o.persona?freshP(ctx,o.pool(ctx,a,b,true),a):fresh(ctx,o.pool(ctx,a,b));
if(!t)return null;
var ex=o.ex?o.ex(ctx,a,b):null;
if(o.fx)o.fx(ctx,a,b,c);
var sp=o.spot?o.spot(ctx,a,b):spotHere(ctx,a,b);
var r={text:fill(ctx,t,a,b,c,ex),why:W(ctx,sp)+(typeof o.why==='function'?o.why(ctx,a,b,c):o.why)};
if(o.food&&HK.Food&&HK.Food.any([a,b])){var fm=HK.Food.daily(ctx,o.food,a,b,null);if(fm){r.text+=fm.text;r.why+='／'+fm.why;}}
if(c)r.with=[c];
if(o.cat2)r.cat=o.cat2(ctx,a,b,c);
return r;
}
};
if(o.persona){var pp=o.pool;o.pool=function(ctx,a,b,raw){var P=pp(ctx,a,b);return raw?P:P[att(a)].concat(P[NEAR[att(a)][0]]);};}
EV.push(e);
return e;
}
