if(tt)emit(ctx,{actors:[A,B],cat:'romance',text:fill(ctx,tt,A,B),why:W(ctx,'旅先')+'休日の小さな旅（'+dayLabel(ctx.env,f.day)+'）',tag:'trip',fx:relFx(ctx,A,B,{aff:3,att:2},{aff:3,att:2})});
