pl.date=f.hol&&rng()<[0.35,0.4,0.6,0.75,0.8,0.8][s]*(lv||s<2?1:0.6);
pl.eve= !pl.date&&rng()<[0.22,0.25,0.3,0.42,0.42,0.42][s];
if(couple(ctx,a,b)&&s>=3&&(pl.date||pl.eve)&&(f.hol||f.fri)&&rng()<0.4*f.pace+0.1){pl.visit=true;pl.first= !f.beds[k];}
