var m=(c.posFor&&typeof c.posFor==='object'?c.posFor:null)||(c.src&&c.src.posFor&&typeof c.src.posFor==='object'?c.src.posFor:null);
if(!m)return'';
var k=idxOf(o);
if(k==null||k===idxOf(c))return'';
