function lean(c){
var t=c.tr||{};
return(t.cp||0)*0.4+(t.lead||0)*0.3+(t.aggr||0)*0.3-(t.ac||0)*0.35+(t.cold||0)*0.1;
}
function key(a,b){var x=a.name||String(a.i),y=b.name||String(b.i);return x<y?x+'\u0001'+y:y+'\u0001'+x;}
