if(res.pairs.some(function(p,k){var q=r0.pairs[k];return q.label!=='strangers'||p.label!=='strangers'?q.name!==p.name||q.cls!==p.cls||(q.dir==null?null:q.dir)!==(p.dir==null?null:p.dir):false;}))return false;
