;
/* ==== js/state-store.js ==== */
HK.Load.def(271,'js/state-store.js',function(){
(function(){
'use strict';
var HK=window.HK;
if(!HK|| !HK.store)return;
var KS=HK.STORE,K=function(k){return KS?KS.key(k):k;};
var PFX=KS?KS.prefix:'hakoniwa:';
var DB=K('hakoniwa-state'),OLD='hakoniwa-state',ST='state',KV='kv',VER=1;
var BIG=['state','state:backup','state:rescue'],WATCH={state:1,adv:1,history:1};
var LS_MAX=1000000,MARK='hakoniwa-idb',WAIT_MAX=8000;
var mem={},memSeq={},meta={},lsSeq={},seq=0,held={},fails=0;
var checking=false,boot0=null,recovered='',first=null,dirty=false;
var mode='ls';
var subs=[];
function isBig(k){return BIG.indexOf(k)>=0;}
function hasIDB(){try{return!!window.indexedDB;}catch(e){return false;}}
function lsGet(k){try{return window.localStorage.getItem(PFX+k);}catch(e){return null;}}
function lsSet(k,v){try{window.localStorage.setItem(PFX+k,v);return true;}catch(e){return false;}}
function lsDel(k){try{window.localStorage.removeItem(PFX+k);}catch(e){}}
function flagKey(k){return'hk-stateidb:'+DB+':'+k;}
function flagGet(k){try{return window.localStorage.getItem(flagKey(k))!=null;}catch(e){return false;}}
function flagSet(k,on){try{if(on)window.localStorage.setItem(flagKey(k),'1');else window.localStorage.removeItem(flagKey(k));}catch(e){}}
function markerOf(text){
if(typeof text!=='string'||text.length>4000||text.indexOf('"'+MARK+'"')<0)return null;
try{var o=JSON.parse(text);return o&&typeof o==='object'&&o[MARK]?o:null;}catch(e){return null;}
}
function metaOf(k,o){
var st=k==='state'?o:o&&o.state;
return{
v:o&&o.v||0,at:(o&&(o.savedAt||o.at))||0,
n:st&&Array.isArray(st.chars)?st.chars.length:0,ties:st&&Array.isArray(st.ties)?st.ties.length:0,
scenId:k==='state'&&o&&typeof o.scenId==='string'?o.scenId:undefined
};
}
function toast(m){try{if(HK.UI&&HK.UI.toast)HK.UI.toast(m);else if(HK.toast)HK.toast(m);}catch(e){}}
function emit(k){subs.forEach(function(f){try{f(k);}catch(e){if(window.console)console.error(e);}});}
var idb=null,opening=null;
function open(){
if(idb!==null)return Promise.resolve(idb);
if(opening)return opening;
opening=new Promise(function(ok){
var done=function(d){idb=d;opening=null;ok(d);};
try{
if(!hasIDB())return done(false);
var rq=indexedDB.open(DB,VER);
rq.onupgradeneeded=function(){
var d=rq.result;
if(!d.objectStoreNames.contains(ST))d.createObjectStore(ST,{keyPath:'k'});
if(!d.objectStoreNames.contains(KV))d.createObjectStore(KV,{keyPath:'k'});
};
rq.onsuccess=function(){
var d=rq.result;
d.onversionchange=function(){try{d.close();}catch(e){}idb=null;};
done(d);
};
rq.onerror=function(e){if(e&&e.preventDefault)e.preventDefault();done(false);};
rq.onblocked=function(){done(false);};
}catch(e){done(false);}
});
return opening;
}
function getKeys(d,store,keys){
return new Promise(function(ok){
try{
var os=d.transaction(store,'readonly').objectStore(store),m={},left=keys.length;
if(!left)return ok(m);
keys.forEach(function(k){
var rq=os.get(k);
rq.onsuccess=function(){if(rq.result)m[k]=rq.result;if(!--left)ok(m);};
rq.onerror=function(){if(!--left)ok(m);};
});
}catch(e){ok(null);}
});
}
function getAll(d,store){
return new Promise(function(ok){
try{
var rq=d.transaction(store,'readonly').objectStore(store).getAll();
rq.onsuccess=function(){var m={};(rq.result||[]).forEach(function(r){if(r&&r.k)m[r.k]=r;});ok(m);};
rq.onerror=function(){ok(null);};
}catch(e){ok(null);}
});
}
function readOther(name,k){
return new Promise(function(ok){
try{
var rq=indexedDB.open(name),fresh=false;
rq.onupgradeneeded=function(e){if(!e.oldVersion){fresh=true;try{rq.transaction.abort();}catch(x){}}};
rq.onerror=function(e){if(e&&e.preventDefault)e.preventDefault();ok(null);};
rq.onblocked=function(){ok(null);};
rq.onsuccess=function(){
var d=rq.result;
if(fresh|| !d.objectStoreNames.contains(ST)){d.close();return ok(null);}
getAll(d,ST).then(function(m){d.close();ok(m&&m[k]&&typeof m[k].text==='string'?m[k]:null);});
};
}catch(e){ok(null);}
});
}
var pend={},inflight=0,FLIGHT=3,waiters=[],sched=false;
function queue(k){
pend[k]=1;
if(sched)return;
sched=true;
Promise.resolve().then(function(){sched=false;pump();});
}
function pump(){
if(checking||inflight>=FLIGHT)return;
var ks=Object.keys(pend);
if(!ks.length){if(!inflight){var w=waiters;waiters=[];w.forEach(function(f){f();});}return;}
inflight++;pend={};
var at={};ks.forEach(function(k){at[k]=memSeq[k]||0;});
var write=function(d){
if(!d)return false;
return new Promise(function(ok){
try{
var tx=d.transaction(ST,'readwrite'),os=tx.objectStore(ST);
ks.forEach(function(k){if(mem[k]==null)os.delete(k);else os.put({k:k,text:mem[k],seq:at[k],at:Date.now(),meta:meta[k]||{}});});
tx.oncomplete=function(){ok(true);};
tx.onerror=tx.onabort=function(e){if(e&&e.preventDefault)e.preventDefault();ok(false);};
if(typeof tx.commit==='function')try{tx.commit();}catch(e){}
}catch(e){ok(false);}
});
};
(idb?Promise.resolve(write(idb)):open().then(write)).then(function(ok){
ks.forEach(function(k){after(k,at[k],ok);});
inflight--;pump();
});
}
function after(k,s,ok){
if(ok){
if((lsSeq[k]||0)>=s)return;
if(mem[k]==null){lsDel(k);return;}
if(memSeq[k]!==s)return;
var m=meta[k]||{},mk={n:m.n||0,ties:m.ties||0,at:m.at||0,v:m.v||0,note:'住人・関係はこのブラウザの IndexedDB にあります（'+DB+'）'};
mk[MARK]=DB;
if(m.scenId)mk.scenId=m.scenId;
if(!lsSet(k,JSON.stringify(mk)))lsDel(k);
return;
}
fails++;
if(mem[k]!=null&&memSeq[k]===s&&(lsSeq[k]||0)<s&&lsSet(k,mem[k])){lsSeq[k]=s;return;}
if(k==='state'&&mem[k]!=null&&memSeq[k]===s)toast('住人をブラウザに保存できませんでした（保存領域がいっぱいかもしれません）。「まるごと書き出し」でファイルに残してください');
if(window.console)console.warn('住人の保存を IndexedDB に書けませんでした：'+k);
}
function setText(k,text,obj){
if(text!=null&&typeof text!=='string')text=JSON.stringify(text);
if(held[k])return false;
if(recovered==='reload')return true;
if(mode!=='idb'){
if(text==null){lsDel(k);emit(k);return true;}
if(!lsSet(k,text))return false;
emit(k);
return true;
}
if(checking&&k==='state'){var b=text==null?'':body(text);if(first==null)first=b;else if(b!==first)dirty=true;}
seq++;
mem[k]=text;memSeq[k]=seq;
if(text!=null){var o=obj;if(!o){try{o=JSON.parse(text);}catch(e){o=null;}}meta[k]=metaOf(k,o);}else delete meta[k];
if(text==null){lsDel(k);lsSeq[k]=seq;flagSet(k,false);}
else if(text.length<=LS_MAX&&lsSet(k,text)){lsSeq[k]=seq;flagSet(k,false);}
else{lsDel(k);flagSet(k,true);}
queue(k);
emit(k);
return true;
}
function getText(k){
if(mode==='idb')return mem[k]!=null?mem[k]:null;
var t=lsGet(k);
return markerOf(t)?null:t;
}
function get(k,d){var t=getText(k);if(t==null)return d;try{return JSON.parse(t);}catch(e){return d;}}
function flush(){
if(mode!=='idb')return Promise.resolve(true);
return new Promise(function(ok){waiters.push(function(){ok(true);});pump();});
}
function clear(){
BIG.forEach(function(k){lsDel(k);flagSet(k,false);delete mem[k];delete meta[k];});
if(mode!=='idb')return Promise.resolve(true);
return open().then(function(d){
if(!d)return true;
return new Promise(function(ok){try{var tx=d.transaction(ST,'readwrite');tx.objectStore(ST).clear();tx.oncomplete=function(){ok(true);};tx.onerror=tx.onabort=function(){ok(false);};}catch(e){ok(false);}});
});
}
function kvGet(key){
return open().then(function(d){
if(!d)return null;
return new Promise(function(ok){try{var rq=d.transaction(KV,'readonly').objectStore(KV).get(key);rq.onsuccess=function(){ok(rq.result||null);};rq.onerror=function(){ok(null);};}catch(e){ok(null);}});
});
}
function kvPut(rec){
return open().then(function(d){
if(!d)return false;
return new Promise(function(ok){
try{
var tx=d.transaction(KV,'readwrite');
if(rec&&rec.del)tx.objectStore(KV).delete(rec.k);else tx.objectStore(KV).put(rec);
tx.oncomplete=function(){ok(true);};tx.onerror=tx.onabort=function(e){if(e&&e.preventDefault)e.preventDefault();ok(false);};
}catch(e){ok(false);}
});
});
}
var get0=HK.store.get,set0=HK.store.set;
HK.store.get=function(k,d){return isBig(k)?get(k,d):get0.apply(this,arguments);};
HK.store.set=function(k,v){
if(!isBig(k)){var r=set0.apply(this,arguments);if(r&&WATCH[k])emit(k);return r;}
var t;
try{t=JSON.stringify(v);}catch(e){return false;}
return setText(k,t===undefined?null:t,v);
};
var readyFn,ready=new Promise(function(ok){readyFn=ok;});
var L=HK.Load,gate=null;
function canHold(){return!!(L&&typeof L.def==='function'&&typeof L.done==='function'&&L.file==='js/state-store.js');}
function hold(){
if(!canHold())return false;
var def0=L.def,done0=L.done,q=[];
L.def=function(){q.push([def0,arguments]);};
L.done=function(){q.push([done0,arguments]);};
gate=function(){
L.def=def0;L.done=done0;
q.forEach(function(x){x[0].apply(L,x[1]);});
q=[];
};
return true;
}
function finish(m,keep){
mode=m;
if(!keep)held={};
if(gate){var g=gate;gate=null;g();}
readyFn(mode);
}
function atOf(k,text){
try{var o=JSON.parse(text);return o&&typeof o==='object'? +(k==='state'?o.savedAt:o.at)||0:0;}catch(e){return 0;}
}
function newer(k,t,R){
if(!R||typeof R.text!=='string'||t==null||markerOf(t)||R.text===t)return false;
var a=atOf(k,t),b= +R.at||atOf(k,R.text);
return a>0&&b>a;
}
function body(text){
try{var o=JSON.parse(text);if(o&&typeof o==='object'){delete o.v;delete o.savedAt;return JSON.stringify(o);}}catch(e){}
return text;
}
function resolve(recs){
var other=[];
BIG.forEach(function(k){
var t=lsGet(k),mk=markerOf(t),R=recs&&recs[k];
if(t!=null&& !mk&&newer(k,t,R)){
mem[k]=R.text;memSeq[k]=R.seq||0;meta[k]=R.meta||{};recovered=recovered||'wait';
if(R.text.length<=LS_MAX&&lsSet(k,R.text))lsSeq[k]=0;else{lsDel(k);flagSet(k,true);}
if(window.console)console.warn('住人の保存：localStorage より IndexedDB のほうが新しいので、IndexedDB から読みました：'+k);
return;
}
if(t!=null&& !mk){
mem[k]=t;lsSeq[k]=0;
if(!R){memSeq[k]=0;try{meta[k]=metaOf(k,JSON.parse(t));}catch(e){meta[k]={};}queue(k);}
else if(R.text===t){memSeq[k]=R.seq||0;meta[k]=R.meta||{};}
return;
}
if(R&&typeof R.text==='string'){mem[k]=R.text;memSeq[k]=R.seq||0;meta[k]=R.meta||{};if(t==null&&k==='state'&& !flagGet(k))recovered=recovered||'idb';return;}
if(mk&&mk[MARK]&&mk[MARK]!==DB)other.push([k,mk[MARK]]);
else if(mk&&window.console)console.warn('住人の保存の印はありますが、IndexedDB に見つかりませんでした：'+k);
});
var R=recs&&recs.state,t=lsGet('state');
if(R&&typeof R.text==='string'&&t!=null&& !markerOf(t)&&t!==R.text&&R.meta&&R.meta.n){
var lv=0;try{var lo=JSON.parse(t);lv=lo&&lo.v||0;}catch(e){lv= -1;}
var bk=get('state:backup',null);
if(lv!==R.meta.v&& !(bk&&bk.at===R.meta.at)){
try{var rs=JSON.parse(R.text);mode='idb';setText('state:backup',JSON.stringify({v:R.meta.v,at:R.meta.at||Date.now(),state:rs}));}catch(e){}
}
}
return Promise.all(other.map(function(x){
return readOther(x[1],x[0]).then(function(r){if(r&&mem[x[0]]==null){mem[x[0]]=r.text;memSeq[x[0]]=0;meta[x[0]]=r.meta||{};queue(x[0]);}});
}));
}
var RKEY='hk-staterecover:'+DB;
function check(){
checking=true;
var end=function(){if(!checking)return;checking=false;clearTimeout(tm);pump();};
var tm=setTimeout(end,WAIT_MAX);
open().then(function(d){
if(!d){if(mode==='idb')mode='ls';return end();}
return getKeys(d,ST,BIG).then(function(recs){
if(!checking)return;
var lost=function(k){var R=recs[k];return boot0[k]==null? !!(R&&typeof R.text==='string'):newer(k,boot0[k],R);};
if(!recs|| !lost('state'))return end();
var ks=BIG.filter(lost);
if(dirty){
if(window.console)console.warn('住人の保存：IndexedDB に新しい保存がありましたが、このページで住人を変えたので、今の住人を保存します');
return end();
}
var last=0;try{last= +window.sessionStorage.getItem(RKEY)||0;}catch(e){last=0;}
if(Date.now()-last<30000){if(window.console)console.warn('住人の保存：IndexedDB から戻すのは続けて行いません');return end();}
try{window.sessionStorage.setItem(RKEY,String(Date.now()));}catch(e){}
ks.forEach(function(k){
var R=recs[k];
mem[k]=R.text;memSeq[k]= ++seq;meta[k]=R.meta||{};
if(R.text.length<=LS_MAX&&lsSet(k,R.text)){lsSeq[k]=seq;flagSet(k,false);}else{lsDel(k);flagSet(k,true);}
});
recovered='reload';
if(window.console)console.warn('住人の保存：localStorage の書き込みが消えていたので、IndexedDB の新しい保存に戻して読み込み直します：'+ks.join(','));
location.reload();
});
}).catch(function(e){if(window.console)console.error('住人の保存の照らし合わせでエラー',e);end();});
}
(function boot(){
if(!hasIDB()){mode='ls';readyFn(mode);return;}
var need=BIG.some(function(k){return markerOf(lsGet(k))||flagGet(k);});
var st0=lsGet('state'),weak=st0==null||st0.indexOf('"sample":true')>=0;
if(!need&& !(weak&&canHold())){
mode='idb';
boot0={};
BIG.forEach(function(k){var t=lsGet(k);boot0[k]=t;if(t!=null){mem[k]=t;memSeq[k]=0;lsSeq[k]=0;}});
readyFn(mode);
check();
return;
}
var gated=hold();
if(!gated){
BIG.forEach(function(k){if(markerOf(lsGet(k)))held[k]=1;});
if(!Object.keys(held).length){mode='ls';readyFn(mode);return;}
}
mode='wait';
var over=false,timer=setTimeout(function(){
over=true;
if(window.console)console.warn('IndexedDB を開けなかったので、住人の保存は localStorage だけを使います');
idb=false;
BIG.forEach(function(k){if(markerOf(lsGet(k)))held[k]=1;});
finish('ls',true);
},WAIT_MAX);
open().then(function(d){
if(over)return;
if(!d){clearTimeout(timer);finish('ls',!gated);return;}
return getKeys(d,ST,BIG).then(function(recs){
if(over)return;
mode='idb';
return resolve(recs||{}).then(function(){if(!over){clearTimeout(timer);finish('idb',!gated);}});
});
}).catch(function(e){
if(over)return;
clearTimeout(timer);
if(window.console)console.error('住人の保存の読み込みでエラー',e);
finish(idb?'idb':'ls',!gated);
});
})();
HK.StateStore={
DB:DB,STORE:ST,KV:KV,LS_MAX:LS_MAX,MARK:MARK,KEYS:BIG.slice(),
ready:ready,get:get,getText:getText,setText:setText,flush:flush,clear:clear,
kvGet:kvGet,kvPut:kvPut,isMarker:function(t){return!!markerOf(t);},
setLimit:function(n){if(n>0)LS_MAX=n;},
on:function(fn){if(typeof fn==='function')subs.push(fn);},
info:function(){
var t=lsGet('state');
return{mode:mode,db:DB,lsFull:t!=null&& !markerOf(t),lsMarker: !!markerOf(t),bytes:mem.state?mem.state.length:(t?t.length:0),fails:fails,checking:checking,recovered:recovered};
}
};
})();
});
;
/* ==== js/save-folder.js ==== */
HK.Load.def(272,'js/save-folder.js',function(){
(function(){
'use strict';
var HK=window.HK;
if(!HK||typeof document==='undefined')return;
var KS=HK.STORE,K=function(k){return KS?KS.key(k):k;};
var CAN=typeof window.showDirectoryPicker==='function';
var DELAY=1500;
var dir=null,dirName='',memOnly=false,rec0=null;
var st='none';
var lastAt=0,errMsg='',fInfo=null,busy=Promise.resolve();
var sig={s:{},h:{}},lastState=null;
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function pad(n){return('0'+n).slice(-2);}
function hm(t){var d=new Date(t);return pad(d.getHours())+':'+pad(d.getMinutes())+':'+pad(d.getSeconds());}
function md(t){var d=new Date(t);return(d.getMonth()+1)+'/'+d.getDate()+' '+pad(d.getHours())+':'+pad(d.getMinutes());}
function toast(m){if(HK.UI&&HK.UI.toast)HK.UI.toast(m);}
function parse(s){try{return JSON.parse(s);}catch(e){return undefined;}}
function SS(){return HK.StateStore;}
function UIS(){return HK.UI&&HK.UI.state?HK.UI.state():null;}
function safeName(id){return String(id||'').replace(/[^\w.-]/g,'_').slice(0,80)||'x';}
function serial(fn){var p=busy.then(fn,fn);busy=p.then(null,function(){});return p;}
function remember(){
if(!SS()|| !dir)return Promise.resolve(false);
if(memOnly)return Promise.resolve(false);
return SS().kvPut({k:'folder',handle:dir,name:dirName,at:Date.now(),sig:sig,last:lastState}).then(function(ok){
if(!ok)memOnly=true;
return ok;
});
}
function sub(name,create){return dir.getDirectoryHandle(name,{create: !!create});}
function writeFile(d,name,text){
return d.getFileHandle(name,{create:true}).then(function(fh){return fh.createWritable();}).then(function(w){
return Promise.resolve(w.write(text)).then(function(){return w.close();});
});
}
function readFile(d,name){
return d.getFileHandle(name).then(function(fh){return fh.getFile();}).then(function(f){return f.text();},function(){return null;});
}
function removeFile(d,name){return Promise.resolve(d.removeEntry(name)).then(null,function(){return false;});}
function names(d){
var out=[];
return new Promise(function(ok){
try{
var it=d.values();
var next=function(){
it.next().then(function(r){if(r.done)return ok(out);if(r.value&&r.value.kind==='file')out.push(r.value.name);next();},function(){ok(out);});
};
next();
}catch(e){ok(out);}
});
}
function lost(e){return e&&(e.name==='NotAllowedError'||e.name==='SecurityError');}
function fail(e){
if(lost(e)){st='perm';bar();}
else{st='err';errMsg=(e&&(e.message||e.name))||'書き込めませんでした';}
if(window.console)console.warn('保存フォルダに書けませんでした',e);
paint();
}
function perm(ask){
if(!dir)return Promise.resolve(false);
var q={mode:'readwrite'};
var chk=function(r){return r==='granted';};
try{
if(typeof dir.queryPermission!=='function')return Promise.resolve(true);
return dir.queryPermission(q).then(function(r){
if(chk(r)|| !ask||typeof dir.requestPermission!=='function')return chk(r);
return dir.requestPermission(q).then(chk);
},function(){return false;});
}catch(e){return Promise.resolve(false);}
}
function env(ls,dbs,extra){
if(HK.Portable&&HK.Portable.envelope)return HK.Portable.envelope(ls,{},dbs,extra);
return{format:'hakoniwa-all',version:1,app:'hakoniwa',exported:new Date().toISOString(),localStorage:ls,localStorageText:{},indexedDB:dbs||[]};
}
function body(S){
var o={};
Object.keys(S||{}).forEach(function(k){if(k!=='v'&&k!=='savedAt'&&k!=='sample')o[k]=S[k];});
o.chars=(o.chars||[]).map(function(c){var x={};Object.keys(c||{}).forEach(function(k){if(k!=='icon')x[k]=c[k];});return x;});
return JSON.stringify(o);
}
function stateData(){
var S=UIS();
if(!S)return null;
var c=JSON.parse(JSON.stringify(S)),ls={};
delete c.sample;
ls[K('hakoniwa:state')]=c;
var adv=HK.store.get('adv',null);
if(adv&&typeof adv==='object')ls[K('hakoniwa:adv')]=adv;
return env(ls,[],{folder:'state',summary:{chars:(c.chars||[]).length,ties:(c.ties||[]).length,saves:0,history:0,keys:Object.keys(ls).length}});
}
function saveData(r){
var db={name:HK.Saves?HK.Saves.DB:K('hakoniwa-saves'),version:1,stores:{}};
db.stores[HK.Saves?HK.Saves.STORE:'saves']={keyPath:'id',autoIncrement:false,records:[r]};
return env({},[db],{folder:'save',summary:{chars:0,ties:0,saves:1,history:0,keys:0}});
}
function histData(h,r){
var ls={};ls[K('hakoniwa:history')]=[h];
var dbs=[];
if(r){var db={name:HK.History?HK.History.DB:K('hakoniwa-history'),version:1,stores:{}};db.stores[HK.History?HK.History.STORE:'results']={keyPath:'id',autoIncrement:false,records:[r]};dbs.push(db);}
return env(ls,dbs,{folder:'history',summary:{chars:0,ties:0,saves:0,history:1,keys:1}});
}
function writeState(force){
if(!dir||(st!=='on'&&st!=='err'&& !force))return Promise.resolve(false);
return serial(function(){
var d=stateData();
if(!d)return false;
var S=d.localStorage[K('hakoniwa:state')];
return writeFile(dir,'state.json',JSON.stringify(d)).then(function(){
lastAt=Date.now();lastState={at:S.savedAt||0};
if(st==='err')st='on';
paint();remember();
return true;
},function(e){fail(e);return false;});
});
}
function sigS(r){return[r.at,r.name||'',r.memo||'',r.title||''].join('|');}
function sigH(h,r){return[h.t||0,h.r?1:0,r?1:0].join('|');}
function syncSaves(){
if(!dir||(st!=='on'&&st!=='hold')|| !HK.Saves)return Promise.resolve(false);
return serial(function(){
return HK.Saves.all().then(function(list){
return sub('saves',true).then(function(d){
return names(d).then(function(have){
var now={},jobs=[];
list.forEach(function(r){
if(!r|| !r.id)return;
var nm=safeName(r.id)+'.json',s=sigS(r);
now[r.id]=s;
if(sig.s[r.id]===s&&have.indexOf(nm)>=0)return;
if(sig.s[r.id]==null&&have.indexOf(nm)>=0)return;
jobs.push(function(){return writeFile(d,nm,JSON.stringify(saveData(r)));});
});
Object.keys(sig.s).forEach(function(id){if(now[id]==null)jobs.push(function(){return removeFile(d,safeName(id)+'.json');});});
return jobs.reduce(function(p,f){return p.then(f);},Promise.resolve()).then(function(){
sig.s=now;lastAt=jobs.length?Date.now():lastAt;paint();remember();return true;
});
});
});
}).then(null,function(e){fail(e);return false;});
});
}
function syncHist(){
if(!dir||(st!=='on'&&st!=='hold')|| !HK.History)return Promise.resolve(false);
return serial(function(){
var list=HK.store.get('history',[]);
if(!Array.isArray(list))list=[];
return HK.History.all().then(function(res){
var byId={};(res||[]).forEach(function(r){if(r&&r.id)byId[r.id]=r;});
return sub('history',true).then(function(d){
return names(d).then(function(have){
var now={},jobs=[];
list.forEach(function(h){
if(!h|| !h.id)return;
var r=byId[h.id]||null,nm=safeName(h.id)+'.json',s=sigH(h,r);
now[h.id]=s;
if(sig.h[h.id]===s&&have.indexOf(nm)>=0)return;
if(sig.h[h.id]==null&&have.indexOf(nm)>=0)return;
jobs.push(function(){return writeFile(d,nm,JSON.stringify(histData(h,r)));});
});
Object.keys(sig.h).forEach(function(id){if(now[id]==null)jobs.push(function(){return removeFile(d,safeName(id)+'.json');});});
return jobs.reduce(function(p,f){return p.then(f);},Promise.resolve()).then(function(){
sig.h=now;lastAt=jobs.length?Date.now():lastAt;paint();remember();return true;
});
});
});
}).then(null,function(e){fail(e);return false;});
});
}
var tState=null,tSaves=[],tHist=null;
function soonState(){if(st!=='on'&&st!=='err')return;clearTimeout(tState);tState=setTimeout(function(){tState=null;writeState();},DELAY);}
function soonSaves(){if(st!=='on'&&st!=='hold')return;tSaves.forEach(clearTimeout);tSaves=[setTimeout(syncSaves,DELAY),setTimeout(syncSaves,6000)];}
function soonHist(){if(st!=='on'&&st!=='hold')return;clearTimeout(tHist);tHist=setTimeout(function(){tHist=null;syncHist();},DELAY);}
function folderState(){
return readFile(dir,'state.json').then(function(t){
if(t==null)return null;
var d=parse(t),s=d&&d.localStorage&&(d.localStorage[K('hakoniwa:state')]||d.localStorage['hakoniwa:state']||d.localStorage['hakoniwa-z:state']);
if(!s||typeof s!=='object')return null;
return{text:t,state:s,at: +s.savedAt||0,n:Array.isArray(s.chars)?s.chars.length:0,ties:Array.isArray(s.ties)?s.ties.length:0};
});
}
function activate(){
st='on';errMsg='';fInfo=null;
paint();unbar();
return folderState().then(function(f){
var S=UIS();
if(f&&f.n&&S&& !(lastState&&lastState.at===f.at)&&(S.sample||body(f.state)!==body(S))){
st='hold';fInfo=f;
paint();bar();
}
var p=st==='on'?writeState():Promise.resolve();
return p.then(syncSaves).then(syncHist);
},function(e){fail(e);});
}
function start(ask){
if(!dir)return Promise.resolve(false);
return perm(ask).then(function(ok){
if(!ok){
st='perm';
if(!ask&&arm()){paint();return false;}
paint();if(!ask&&denies()>=DENY_MAX)return false;
bar();return false;
}
denies(0);
return activate().then(function(){return true;});
});
}
var DENY_MAX=3,armed=null;
function denyKey(){return'hk-sfdeny:'+(SS()?SS().DB:'hakoniwa');}
function denies(set){
try{
if(set===0){window.localStorage.removeItem(denyKey());return 0;}
var n=parseInt(window.localStorage.getItem(denyKey()),10)||0;
if(set===1){n++;window.localStorage.setItem(denyKey(),String(n));}
return n;
}catch(e){return 0;}
}
var EVS=['click','keydown','touchstart'];
function disarm(){if(armed){EVS.forEach(function(k){document.removeEventListener(k,armed,true);});armed=null;}}
function arm(){
disarm();
if(!dir||typeof dir.requestPermission!=='function'||denies()>=DENY_MAX)return false;
var h=dir;
armed=function(ev){
disarm();
if(dir!==h||st!=='perm')return;
if(ev&&ev.target&&ev.target.closest&&ev.target.closest('[data-sf]'))return;
var p;
try{p=h.requestPermission({mode:'readwrite'});}catch(e){p=Promise.reject(e);}
Promise.resolve(p).then(function(r){
if(dir!==h)return;
if(r==='granted'){denies(0);return activate();}
denies(1);paint();bar();
},function(e){
if(dir!==h)return;
if(!(e&&e.name==='SecurityError'))denies(1);
paint();bar();
});
};
EVS.forEach(function(k){document.addEventListener(k,armed,true);});
return true;
}
var FILE= /^file:/.test(location.protocol);
var ALWAYS='Chrome の確認で「常に許可」を選ぶと、次に開いたときは確認なしで使えます。'+(FILE?'手元のファイル（file://）で開いているので、ブラウザの仕様で毎回確認が要ります。':'');
function unbar(){var b=document.getElementById('sfbar');if(b)b.remove();}
function bar(){
unbar();
if(!dir||(st!=='perm'&&st!=='hold'))return;
var box=document.createElement('div');
box.id='sfbar';box.setAttribute('role','status');box.className='sfbar';
if(st==='perm'){
box.innerHTML='<span>保存フォルダ<b>〈'+esc(dirName)+'〉</b>を使う<br><small>'+esc(ALWAYS)+'</small></span><button type="button" class="btn small primary" data-sf="allow">許可</button><button type="button" class="btn small ghost" data-sf="later">今回は使わない</button>';
}else{
var S=UIS(),f=fInfo||{};
box.innerHTML='<span>保存フォルダ〈'+esc(dirName)+'〉の住人のほうが新しいです（フォルダ：'+(f.at?md(f.at)+' 保存・':'')+'住人'+(f.n||0)+'人・関係'+(f.ties||0)+'本／このブラウザ：'+(S&&S.sample?'サンプルの住人':'住人'+(S?S.chars.length:0)+'人・関係'+(S?(S.ties||[]).length:0)+'本')+'）。読み込むまで、フォルダへの住人の書き込みを止めています</span>'+
(S&&S.sample?'<button type="button" class="btn small primary" data-sf="readrep">読み込む</button>'
:'<button type="button" class="btn small primary" data-sf="readrep">読み込む（置き換え）</button><button type="button" class="btn small" data-sf="readadd">足す</button>')+
'<button type="button" class="btn small ghost" data-sf="keep">このブラウザのまま</button>';
}
var host=document.querySelector('main')||document.body;
host.insertBefore(box,host.firstChild);
}
function readFolder(how){
if(!dir)return;
if(!HK.Portable|| !HK.Portable.importMany){toast('読み込めませんでした');return;}
var say=HK.Portable.say||toast;
perm(true).then(function(ok){
if(!ok){st='perm';paint();bar();say('保存フォルダを使う許可がありません');return;}
say('保存フォルダを読んでいます…');
var items=[],fAt=0;
return readFile(dir,'state.json').then(function(t){
if(t!=null){items.push({name:'state.json',text:t});var d=parse(t),s=d&&d.localStorage&&d.localStorage[K('hakoniwa:state')];fAt=s&& +s.savedAt||0;}
var each=function(sd){
return sub(sd,false).then(function(d){
return names(d).then(function(ns){
ns=ns.filter(function(n){return/\.json$/i.test(n);});
return ns.reduce(function(p,n){return p.then(function(){return readFile(d,n).then(function(x){if(x!=null)items.push({name:sd+'/'+n,text:x});});});},Promise.resolve());
});
},function(){});
};
return each('saves').then(function(){return each('history');});
}).then(function(){
if(!items.length){say('保存フォルダに、読み込めるファイル（state.json・saves・history）がありませんでした');return;}
var prev=st,prevLast=lastState;
lastState={at:fAt};st='busy';unbar();paint();
return remember().then(function(){
return HK.Portable.importMany(items,how==='rep'?'rep':'add',{label:'保存フォルダから読み込みました（'+(how==='rep'?'置き換え':'足す')+'）'});
}).then(function(started){
if(started!==false)return;
st=prev;lastState=prevLast;remember();paint();if(st==='hold'||st==='perm')bar();
});
});
}).then(null,function(e){fail(e);});
}
function keepBrowser(){
var f=fInfo;
st='on';fInfo=null;unbar();paint();
var p=f&&f.text?serial(function(){return writeFile(dir,'state-prev.json',f.text);}):Promise.resolve();
p.then(function(){return writeState();}).then(function(ok){if(ok)toast('保存フォルダの住人を、このブラウザの内容にしました（前の内容は state-prev.json に残しました）');},fail);
}
function pick(){
if(!CAN)return;
var o={id:'hakoniwa-save',mode:'readwrite'};
var p;
try{p=window.showDirectoryPicker(o);}catch(e){p=Promise.reject(e);}
p.then(function(h){
disarm();denies(0);
dir=h;dirName=h.name||'フォルダ';memOnly=false;
if(!rec0||rec0.name!==dirName){sig={s:{},h:{}};lastState=null;}
return remember().then(function(){return start(true);}).then(function(ok){
if(ok)toast('保存フォルダ〈'+dirName+'〉を使います'+(memOnly?'（このブラウザでは覚えられないので、次に開いたときはもう一度選んでください）':''));
});
},function(e){
if(e&&e.name==='AbortError')return;
errMsg=(e&&e.name==='SecurityError')?'このページではフォルダを選べませんでした（ブラウザの制限）':'フォルダを選べませんでした';
st=dir?st:'none';paint();toast(errMsg);
});
}
function forget(){
if(!window.confirm('保存フォルダ〈'+dirName+'〉を使うのをやめますか？（フォルダの中のファイルはそのまま残ります）'))return;
disarm();dir=null;dirName='';st='none';sig={s:{},h:{}};lastState=null;rec0=null;unbar();
if(SS())SS().kvPut({k:'folder',del:1});
paint();toast('保存フォルダを使うのをやめました');
}
function statusText(){
if(!dir)return errMsg||'まだ選んでいません';
var nm='〈'+esc(dirName)+'〉';
if(st==='perm')return nm+(armed?'：ページを操作すると、使う許可を確かめます':denies()>=DENY_MAX&& !document.getElementById('sfbar')?'：許可されなかったので、今回は使いません（［許可する］で使えます）':'：使うには許可が要ります（画面の上の［許可］か、［許可する］）');
if(st==='hold')return nm+'：フォルダの住人のほうが新しいので、住人の書き込みを止めています（画面の上の知らせから選んでください）';
if(st==='err')return nm+'：書き込めませんでした（'+esc(errMsg)+'）。次に住人が変わったときに、もう一度書きます';
if(st==='busy')return nm+'から読み込んでいます…';
return nm+'に保存しています'+(lastAt?'（最後に書いた時刻 '+hm(lastAt)+'）':'')+(memOnly?'。このブラウザでは選んだフォルダを覚えられないので、次に開いたときはもう一度選んでください':'');
}
var helpOpen=false;
function html(){
var h='<div class="sfold" id="sfold">';
if(!CAN)return h+'<p class="hint sfna">このブラウザでは使えません（PC の Chrome／Edge で使えます）。別の端末へは「まるごと」のタブから移せます。</p></div>';
return h+'<div class="sfrow"><span class="sfstat" id="sf-stat" aria-live="polite">'+statusText()+'</span>'+
'<span class="sfacts"><button class="btn small'+(dir?'':' primary')+'" data-sf="pick">'+(dir?'フォルダを選び直す':'フォルダを選ぶ')+'</button>'+
(dir&&st==='perm'?'<button class="btn small primary" data-sf="allow">許可する</button>':'')+
(dir?'<button class="btn small ghost" data-sf="forget">使うのをやめる</button>':'')+
'<button type="button" class="tipbtn" data-sf="help" aria-expanded="'+helpOpen+'" aria-controls="sf-help" aria-label="保存フォルダの説明" title="説明">？</button></span></div>'+
(dir?'<div class="ctblk"><div class="ctrow"><button class="btn small" data-sf="read">フォルダから読み込む</button>'+(HK.Portable&&HK.Portable.modeHtml?HK.Portable.modeHtml():'')+'</div><p class="ctdesc">ブラウザのデータが消えたときなどに、フォルダの中身から戻します。</p></div>':'')+
'<p class="hint sfhelp" id="sf-help"'+(helpOpen?'':' hidden')+'>PC の Chrome／Edge で使えます。選んだフォルダに、住人・関係が変わるたびに state.json、セーブは saves フォルダ、履歴は history フォルダに書き込みます（どれも「まるごと読み込む」で読めるファイルです）。ブラウザのデータが消えても、フォルダから戻せます。'+esc(ALWAYS)+'</p></div>';
}
function paint(){
if(HK.CastTools&&HK.CastTools.mark)HK.CastTools.mark();
var el=document.getElementById('sfold');
if(!el)return;
var tmp=document.createElement('div');tmp.innerHTML=html();
el.parentNode.replaceChild(tmp.firstChild,el);
}
(function style(){
var s=document.createElement('style');
s.textContent='.sfold{display:flex;flex-direction:column;gap:14px;min-width:0}.sfold .sfna{opacity:.7;margin:0}.sfrow{display:flex;flex-wrap:wrap;gap:8px 12px;align-items:center;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r,4px)}'+
'.sfstat{flex:1 1 220px;min-width:0;font-size:13px;line-height:1.6}.sfacts{display:inline-flex;flex-wrap:wrap;gap:6px;align-items:center}.sfhelp{margin:0;font-size:12px}.sfhelp[hidden]{display:none}'+
'.sfbar{margin:8px 0 12px;padding:10px 12px;border:1px solid var(--accent);border-radius:var(--r,8px);background:var(--accent-soft,var(--surface));color:var(--ink);line-height:1.6;display:flex;flex-wrap:wrap;gap:6px 8px;align-items:center}.sfbar span{flex:1 1 260px;min-width:0}';
(document.head||document.documentElement).appendChild(s);
})();
document.addEventListener('click',function(ev){
var t=ev.target.closest&&ev.target.closest('[data-sf]');
if(t){
var k=t.dataset.sf;
if(k==='pick')pick();
else if(k==='allow'){disarm();start(true).then(function(ok){if(!ok){denies(1);toast('許可されませんでした');}});}
else if(k==='later'){unbar();paint();}
else if(k==='read')readFolder(HK.Portable&&HK.Portable.mode?HK.Portable.mode():'add');
else if(k==='readrep')readFolder('rep');
else if(k==='readadd')readFolder('add');
else if(k==='keep')keepBrowser();
else if(k==='forget')forget();
else if(k==='help'){helpOpen= !helpOpen;paint();var hb=document.querySelector('[data-sf="help"]');if(hb)hb.focus();}
return;
}
if(ev.target.closest&&ev.target.closest('[data-act="saveres"],[data-sv="del"]'))soonSaves();
});
document.addEventListener('change',function(ev){
var t=ev.target;
if(t&&(t.id==='savefile'||(t.dataset&&t.dataset.sv==='name')))soonSaves();
});
document.addEventListener('visibilitychange',function(){
if(document.visibilityState==='hidden'&&tState){clearTimeout(tState);tState=null;writeState();}
});
function wrapFn(obj,key,after){
if(!obj||typeof obj[key]!=='function')return;
var f0=obj[key];
obj[key]=function(){var r=f0.apply(this,arguments);try{after();}catch(e){}return r;};
}
function hook(){
if(SS()&&SS().on)SS().on(function(k){if(k==='state'||k==='adv')soonState();else if(k==='history')soonHist();});
if(HK.Saves){wrapFn(HK.Saves,'put',soonSaves);wrapFn(HK.Saves,'clear',soonSaves);}
if(HK.History){wrapFn(HK.History,'put',soonHist);wrapFn(HK.History,'keep',soonHist);}
}
function boot(){
hook();
if(!CAN|| !SS()|| !SS().kvGet)return;
SS().kvGet('folder').then(function(r){
if(!r|| !r.handle)return;
rec0=r;dir=r.handle;dirName=r.name||r.handle.name||'フォルダ';
if(r.sig&&typeof r.sig==='object')sig={s:r.sig.s||{},h:r.sig.h||{}};
lastState=r.last||null;
return start(false);
});
}
var ready=HK.StateStore&&HK.StateStore.ready?HK.StateStore.ready:Promise.resolve();
ready.then(function(){setTimeout(boot,0);});
HK.SaveFolder={
can:CAN,armed:function(){return!!armed;},html:html,pick:pick,read:readFolder,forget:forget,start:start,
writeState:writeState,syncSaves:syncSaves,syncHist:syncHist,
status:function(){return{st:st,name:dirName,lastAt:lastAt,memOnly:memOnly,err:errMsg,sig:sig,last:lastState};},
useHandle:function(h,ask){dir=h;dirName=h.name||'フォルダ';memOnly=false;if(!rec0||rec0.name!==dirName){sig={s:{},h:{}};lastState=null;}return remember().then(function(){return start(ask!==false);});}
};
})();
});
;
/* ==== js/tips.js ==== */
