S.chars.forEach(function(c){by[c.id]=c;});
if(mode==='page')cv.onPage.forEach(function(i){on[S.chars[i].id]=1;});
T.forEach(function(t,k){
if(mode==='page'&& !on[t.a]&& !on[t.b])return;
if(q&& !(hit(by[t.a],q)||hit(by[t.b],q)))return;
ks.push(k);
});
