var a=C[i-1],b=C[i];
if(reg&&(a.reg||0)>(b.reg||0))reg=false;
if(grp){var ga=gl(a)[0]||'',gb=gl(b)[0]||'';if(ga!==gb&&(!ga||(gb&&coll.compare(ga,gb)>0)))grp=false;}
